/* CSS PART 2 OF 2 */

/* Contact and conversion area */
.contact-section {
  padding-block: var(--section-space);
  background: var(--color-forest);
  color: var(--color-white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 9vw, 120px);
}

.contact-copy {
  max-width: 460px;
}

.contact-copy h2 {
  color: var(--color-cream);
}

.contact-copy p {
  color: rgba(255, 255, 255, 0.76);
  line-height: 1.9;
}

.contact-copy .eyebrow {
  color: var(--color-moss);
}

.contact-details {
  display: flex;
  margin-top: 36px;
  padding-top: 24px;
  flex-direction: column;
  gap: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
}

.contact-detail {
  color: var(--color-cream);
  font-size: 0.9rem;
}

.contact-form {
  display: grid;
  padding: clamp(25px, 4vw, 48px);
  gap: 20px;
  background: var(--color-cream);
  color: var(--color-ink);
}

.form-heading {
  margin-bottom: 5px;
  color: var(--color-forest);
  font-family: var(--font-display);
  font-size: 1.8rem;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field label {
  color: var(--color-forest);
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 52px;
  padding: 13px 15px;
  border: 1px solid #cfd2c7;
  border-radius: var(--radius-sm);
  background: var(--color-paper);
  color: var(--color-ink);
  transition: border-color var(--transition), box-shadow var(--transition);
}

.form-field textarea {
  min-height: 145px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #858b80;
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--color-pine);
  box-shadow: 0 0 0 3px rgba(52, 79, 62, 0.12);
}

.form-submit {
  width: fit-content;
  min-width: 190px;
  border: 0;
}

.form-note {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.75rem;
  line-height: 1.6;
}

/* Footer */
.site-footer {
  padding-block: 55px 28px;
  background: #1b3027;
  color: var(--color-white);
}

.footer-main {
  display: flex;
  padding-bottom: 38px;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
}

.site-footer .brand-lockup {
  color: var(--color-cream);
}

.site-footer .brand-description {
  color: rgba(255, 255, 255, 0.65);
}

.footer-copy {
  max-width: 390px;
  margin: 0;
  color: rgba(255, 255, 255, 0.68);
  font-size: 0.84rem;
}

.footer-bottom {
  display: flex;
  padding-top: 22px;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.18);
}

.footer-bottom p {
  margin: 0;
  color: rgba(255, 255, 255, 0.65);
  font-size: 0.73rem;
}

.footer-contact-link {
  color: var(--color-moss);
  font-size: 0.78rem;
  font-weight: 700;
}

.footer-contact-link:hover {
  color: var(--color-white);
}

/* Accessible mobile navigation */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  padding: 0;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-forest);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* Tablet */
@media (max-width: 900px) {
  :root {
    --section-space: 82px;
  }

  .header-inner {
    min-height: 78px;
  }

  .brand-logo {
    width: 46px;
    height: 46px;
  }

  .primary-nav {
    gap: 17px;
  }

  .header-cta {
    padding-inline: 18px;
  }

  .hero {
    min-height: 650px;
  }

  .intro-section,
  .approach-layout,
  .contact-layout {
    grid-template-columns: 1fr 1fr;
    gap: 42px;
  }

  .services-heading {
    align-items: start;
    flex-direction: column;
  }

  .services-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .service-item:not(:nth-child(3n)) {
    border-right: 0;
  }

  .service-item:not(:nth-child(3n + 1)) {
    padding-left: 0;
  }

  .service-item:nth-child(odd) {
    padding-right: 25px;
    border-right: 1px solid rgba(36, 62, 50, 0.2);
  }

  .service-item:nth-child(even) {
    padding-right: 0;
    padding-left: 25px;
  }

  .design-promotion {
    grid-template-columns: 1fr;
  }

  .footer-main {
    align-items: flex-start;
  }
}

/* Mobile navigation and layout */
@media (max-width: 680px) {
  :root {
    --gutter: 23px;
    --section-space: 70px;
  }

  html {
    scroll-padding-top: 72px;
  }

  body {
    font-size: 15px;
  }

  .header-inner {
    position: relative;
    min-height: 72px;
    flex-wrap: wrap;
    gap: 0;
  }

  .brand-logo {
    width: 42px;
    height: 42px;
  }

  .brand-name {
    font-size: 1.25rem;
  }

  .brand-description {
    font-size: 0.52rem;
  }

  .menu-toggle {
    display: flex;
    margin-left: auto;
  }

  .primary-nav {
    display: none;
    width: 100%;
    padding: 12px 0 20px;
    align-items: stretch;
    flex-direction: column;
    gap: 0;
    border-top: 1px solid var(--color-line);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .nav-link {
    display: block;
    width: 100%;
    padding: 12px 4px;
    overflow-wrap: anywhere;
    white-space: normal;
  }

  .nav-link::after {
    display: none;
  }

  .header-cta {
    display: none;
  }

  .hero {
    min-height: 670px;
    min-height: min(720px, calc(100svh - 72px));
    align-items: end;
    background-position: 58% center;
    background-image:
      linear-gradient(
        0deg,
        rgba(24, 45, 34, 0.94) 0%,
        rgba(24, 45, 34, 0.76) 45%,
        rgba(24, 45, 34, 0.17) 100%
      ),
      url("/images/landscape-hero.jpg");
  }

  .hero-content {
    padding-block: 100px 75px;
  }

  .hero h1 {
    font-size: clamp(3rem, 12vw, 4.6rem);
  }

  .hero-description {
    font-size: 0.97rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-note {
    font-size: 0.68rem;
    line-height: 1.7;
  }

  .intro-section,
  .approach-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .intro-copy p {
    font-size: 0.97rem;
  }

  .credential-line {
    gap: 16px;
  }

  .credential {
    width: 100%;
  }

  .services-heading {
    margin-bottom: 32px;
    gap: 12px;
  }

  .services-list {
    grid-template-columns: 1fr;
  }

  .service-item,
  .service-item:not(:nth-child(3n)),
  .service-item:nth-child(odd),
  .service-item:nth-child(even) {
    min-height: auto;
    padding: 26px 0;
    border-right: 0;
    border-bottom: 1px solid rgba(36, 62, 50, 0.2);
  }

  .service-number {
    margin-bottom: 14px;
  }

  .service-item h3 {
    margin-bottom: 8px;
  }

  .approach-panel {
    padding: 34px 27px;
  }

  .design-promotion {
    padding: 36px 27px;
    gap: 25px;
  }

  .design-promotion .button {
    width: 100%;
  }

  .contact-form {
    padding: 25px 20px;
  }

  .form-submit {
    width: 100%;
  }

  .footer-main {
    padding-bottom: 28px;
    flex-direction: column;
    gap: 22px;
  }

  .footer-copy {
    max-width: 100%;
  }

  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }
}

/* Small mobile */
@media (max-width: 380px) {
  :root {
    --gutter: 18px;
  }

  .brand-lockup {
    gap: 8px;
  }

  .brand-name {
    font-size: 1.1rem;
  }

  .brand-description {
    font-size: 0.47rem;
  }

  .menu-toggle {
    width: 42px;
    height: 42px;
  }

  .hero h1 {
    font-size: 2.85rem;
  }

  .button {
    padding-inline: 18px;
  }
}

/* Visible keyboard focus */
:focus-visible {
  outline: 3px solid #c39b64;
  outline-offset: 4px;
}

.menu-toggle:focus-visible,
.form-field input:focus-visible,
.form-field textarea:focus-visible,
.form-field select:focus-visible {
  outline: 3px solid var(--color-earth);
  outline-offset: 3px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
